49	    /// <summary>
50	    /// Configures eShop projects to use OpenAI for text embedding and chat.
51	    /// </summary>
52	    public static IDistributedApplicationBuilder AddOpenAI(this IDistributedApplicationBuilder builder,
53	        IResourceBuilder<ProjectResource> catalogApi,
54	        IResourceBuilder<ProjectResource> webApp,
55	        OpenAITarget openAITarget)
56	    {
57	        const string openAIName = "openai";
58	
59	        const string textEmbeddingName = "textEmbeddingModel";
60	        const string textEmbeddingModelName = "text-embedding-3-small";
61	
62	        const string chatName = "chatModel";
63	        const string chatModelName = "gpt-4.1-mini";
64	
65	        if (openAITarget != OpenAITarget.AzureOpenAI)
66	        {
67	#pragma warning disable ASPIREINTERACTION001 // Type is for evaluation purposes only and is subject to change or removal in future updates. Suppress this diagnostic to proceed.
68	            IResourceBuilder<ParameterResource>? endpoint = null;
69	            if (openAITarget != OpenAITarget.OpenAI)
70	            {
71	                endpoint = builder.AddParameter("OpenAIEndpointParameter")
72	                    .WithDescription("The Azure OpenAI endpoint to use, e.g. https://<name>.openai.azure.com/")
73	                    .WithCustomInput(p => new()
74	                    {
75	                        Name = "OpenAIEndpointParameter",
76	                        Label = "Azure OpenAI Endpoint",
