79	                    });
80	            }
81	
82	            IResourceBuilder<ParameterResource>? key = null;
83	            if (openAITarget is OpenAITarget.OpenAI or OpenAITarget.AzureOpenAIExistingWithKey)
84	            {
85	                key = builder.AddParameter("OpenAIKeyParameter", secret: true)
86	                    .WithDescription("The OpenAI API key to use.")
87	                    .WithCustomInput(p => new()
88	                    {
89	                        Name = "OpenAIKeyParameter",
90	                        Label = "API Key",
91	                        InputType = InputType.SecretText
92	                    });
93	            }
94	
95	            var chatModel = builder.AddParameter("ChatModelParameter")
96	                .WithDescription("The chat model to use.")
97	                .WithCustomInput(p => new()
98	                {
99	                    Name = "ChatModelParameter",
100	                    Label = "Chat Model",
101	                    InputType = InputType.Text,
102	                    Value = chatModelName,
103	                });
104	
105	            var embeddingModel = builder.AddParameter("EmbeddingModelParameter")
106	                .WithDescription("The embedding model to use.")
107	                .WithCustomInput(p => new()
108	                {
109	                    Name = "EmbeddingModelParameter",
110	                    Label = "Text Embedding Model",
111	                    InputType = InputType.Text,
112	                    Value = textEmbeddingModelName,
113	                });
114	#pragma warning restore ASPIREINTERACTION001
115	
116	            var openAIConnectionBuilder = new ReferenceExpressionBuilder();
117	            if (endpoint is not null)
118	            {
119	                openAIConnectionBuilder.Append($"Endpoint={endpoint}");
120	            }
121	            if (key is not null)
122	            {
123	                openAIConnectionBuilder.Append($";Key={key}");
124	            }
125	            var openAIConnectionString = openAIConnectionBuilder.Build();
126	
127	            catalogApi.WithReference(builder.AddConnectionString(textEmbeddingName, cs =>
128	            {
129	                cs.Append($"{openAIConnectionString};Deployment={embeddingModel}");
130	            }));
131	            webApp.WithReference(builder.AddConnectionString(chatName, cs =>
132	            {
133	                cs.Append($"{openAIConnectionString};Deployment={chatModel}");
134	            }));
135	        }
136	        else
137	        {
138	            var openAI = builder.AddAzureOpenAI(openAIName);
139	
140	            var chat = openAI.AddDeployment(chatName, chatModelName, "2025-04-14")
141	                .WithProperties(d =>
142	                {
143	                    d.DeploymentName = chatModelName;
144	                    d.SkuName = "GlobalStandard";
145	                    d.SkuCapacity = 50;
146	                });
147	            var textEmbedding = openAI.AddDeployment(textEmbeddingName, textEmbeddingModelName, "1")
148	                .WithProperties(d =>
149	                {
150	                    d.DeploymentName = textEmbeddingModelName;
151	                    d.SkuCapacity = 20; // 20k tokens per minute are needed to seed the initial embeddings
152	                });
153	
154	            catalogApi.WithReference(textEmbedding);
155	            webApp.WithReference(chat);
156	        }
157	
158	        return builder;
