202	            yarp.AddRoute("/catalog-api/api/catalog/items/{id}", catalogCluster)
203	                .WithMatchRouteQueryParameter([new() { Name = "api-version", Values = ["1.0", "1", "2.0"], Mode = QueryParameterMatchMode.Exact }])
