212	                .WithTransformPathRemovePrefix("/catalog-api");
213	
214	            yarp.AddRoute("/catalog-api/api/catalog/items/withsemanticrelevance", catalogCluster)
215	                .WithMatchRouteQueryParameter([new() { Name = "api-version", Values = ["2.0"], Mode = QueryParameterMatchMode.Exact }])
216	                .WithTransformPathRemovePrefix("/catalog-api");
217	
218	            yarp.AddRoute("/catalog-api/api/catalog/items/type/{typeId}/brand/{brandId?}", catalogCluster)
219	                .WithMatchRouteQueryParameter([new() { Name = "api-version", Values = ["1.0", "1"], Mode = QueryParameterMatchMode.Exact }])
220	                .WithTransformPathRemovePrefix("/catalog-api");
221	
222	            yarp.AddRoute("/catalog-api/api/catalog/items/type/all/brand/{brandId?}", catalogCluster)
223	                .WithMatchRouteQueryParameter([new() { Name = "api-version", Values = ["1.0", "1"], Mode = QueryParameterMatchMode.Exact }])
224	                .WithTransformPathRemovePrefix("/catalog-api");
225	
226	            yarp.AddRoute("/catalog-api/api/catalog/catalogTypes", catalogCluster)
227	                .WithMatchRouteQueryParameter([new() { Name = "api-version", Values = ["1.0", "1", "2.0"], Mode = QueryParameterMatchMode.Exact }])
228	                .WithTransformPathRemovePrefix("/catalog-api");
229	
230	            yarp.AddRoute("/catalog-api/api/catalog/catalogBrands", catalogCluster)
231	                .WithMatchRouteQueryParameter([new() { Name = "api-version", Values = ["1.0", "1", "2.0"], Mode = QueryParameterMatchMode.Exact }])
232	                .WithTransformPathRemovePrefix("/catalog-api");
233	
