236	                .WithTransformPathRemovePrefix("/catalog-api");
237	
238	            // Generic catalog catch-all route
239	            yarp.AddRoute("/api/catalog/{*any}", catalogCluster)
240	                .WithMatchRouteQueryParameter([new() { Name = "api-version", Values = ["1.0", "1", "2.0"], Mode = QueryParameterMatchMode.Exact }]);
